def svg(label, body, height=280):
    return f'<div class="diagram-scroll" tabindex="0" style="max-width:100%;overflow-x:auto"><svg xmlns="http://www.w3.org/2000/svg" style="display:block;width:100%;height:auto;min-width:720px" viewBox="0 0 800 {height}" role="img" aria-label="{label}"><rect width="800" height="{height}" rx="20" fill="#f1f5f5"/><g font-family="system-ui,Microsoft YaHei,sans-serif" font-size="18" fill="#203448">{body}</g></svg></div>'

def text(x,y,t,fill=None,size=None):
    return f'<text x="{x}" y="{y}"'+(f' fill="{fill}"' if fill else '')+(f' font-size="{size}"' if size else '')+f'>{t}</text>'

def box(x,y,w,h,t,color='#dcebe7'):
    return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="12" fill="{color}"/>'+text(x+14,y+h/2+6,t)

def figure(title,image,caption):
    return f'<figure class="figure" style="margin:20px 0"><h3>{title}</h3>{image}<figcaption>{caption}</figcaption></figure>'

