def split_image(title,counts):
    b=''
    for i,(name,group,rows,color) in enumerate(counts):
        x=30+i*255;b+=box(x,36,230,62,name,color)+text(x+12,133,group)+text(x+12,177,rows)
    return svg(title,b+text(35,245,'同一口井 / 储层组不跨集合；改写和试验点留在原组。',size=17))

