    background=''.join(figure(t,im,cap) for t,im,cap in c['background'])
    workflow=''.join(f'<article class="flow-step"><span class="step-number">{i+1:02d}</span><div><h2>{n}</h2><div class="io-grid"><p><b>输入</b>{inp}</p><p><b>动作</b>{act}</p><p><b>产物</b>{out}</p></div>{im}<p class="note">观察重点：{trap}。</p></div></article>' for i,(n,inp,act,out,trap,im) in enumerate(c['steps']))
    html=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>{c['title']}</title><link rel="stylesheet" href="demo.css"><script defer src="demo.js"></script></head><body class="case-{scene}"><header class="hero"><div class="hero-inner"><p class="eyebrow">{c['eyebrow']}</p><h1>{c['short']}</h1><p class="hero-lede">{c['lede']}</p><div class="hero-tags"><span>独立组留出</span><span>真实前端计算</span><span>可追溯候选</span></div></div></header><nav class="tabs" aria-label="案例内容"><button type="button" data-tab="background" aria-pressed="true">专业背景</button><button type="button" data-tab="workflow" aria-pressed="false">案例流程</button><button type="button" data-tab="lab" aria-pressed="false">可运行示范</button></nav><main><section id="background"><div class="section-intro"><p class="eyebrow">UNDERSTAND THE FIELD</p><h2>先把专业对象看清楚</h2><p>{c['lede']}</p></div>{background}<aside class="source-note"><b>数据与专业来源</b><p>{c['source']}</p><p>来源核对：2026-10-24。图形由本案例以SVG重绘。</p></aside></section><section id="workflow" hidden><div class="section-intro"><p class="eyebrow">FROM OBSERVATION TO EVIDENCE</p><h2>每一步都有输入、动作和产物</h2></div>{workflow}</section><section id="lab" hidden><div class="section-intro"><p class="eyebrow">RUN THE COMPARISON</p><h2>{'让每一个候选都带着出处' if scene=='wo1' else '亲手改变资源边界'}</h2><p>改变输入后点击运行；结果会标记过期，重算完成后才能导出当前JSON。</p></div><section class="panel controls"><div class="section-head"><h2>实验设置</h2><span class="chip">教学合成数据 v1</span></div>{c['controls']}<div class="actions"><button id="run" type="button" class="primary">运行计算</button><button id="reset" type="button">恢复默认</button><button id="export" type="button" disabled>下载当前JSON</button><output id="status" role="status" aria-live="polite">等待运行</output></div></section>{c['outputs']}</section></main><footer><strong>井见 · 扩展案例</strong><span>{scene} / {c['id']} · 1.0.0</span></footer></body></html>'''
